/// <summary>
/// The <c>TFMTranslationLookupCreationProcessBatch</c> class populates the table with label file entries.
/// </summary>
class TFMTranslationLookupCreationProcessBatch extends RunBaseBatch implements BatchRetryable
{
    DialogField         dlgLabelFiles;
    str                 dlgLabelValue;

}

Method.Source:
 //<summary>
 //Adds the Label file names to the dialog box
 //</summary>
 //<returns>
 //The dialog box box.
 //</returns>
public Object dialog()
{
    DialogRunbase               dialog;

    //Setup the dialog
    dialog = super();
    dialog.caption(TFMTranslationLookupCreationProcessBatch::description());

    dlgLabelFiles = dialog.addField(extendedTypeStr(Description255), "Label file name ids e.g. 'TFM;Sys;Syp;Wax;TFDevice'" );
    dlgLabelFiles.value(TFMParameters::GetLabelFileIds());
    dlgLabelFiles.helpText("@TFM:LabelfilenameprefixtofilltheTran");

    return dialog;
}

 //<summary>
 //Retrieves the user entered values from dialog form.
 //</summary>
 //<returns>
 //true if the values are retrieved successfully; otherwise, false.
 //</returns>
public boolean getFromDialog()
{
    boolean ret;

    ret = super();

    if (dlgLabelFiles && dlgLabelFiles.value())
    {
        dlgLabelValue = dlgLabelFiles.value();
    }

    return ret;
}

public boolean unpack(container packedClass)
{
    return true;
}

/// <summary>
/// Runs the creation.
/// </summary>
public void run()
{
    info("@TFM:Start-CreateTranslationLabelfile"); //begin

    TFMFormLookupHelper::createLabelFileLabelIdTranslationTable(dlgLabelValue ? dlgLabelValue : TFMParameters::GetLabelFileIds(), true, true);

    info("@TFM:End-CreatingTranslationLabelfile"); //end
}

public static TFMTranslationLookupCreationProcessBatch construct()
{
    return new TFMTranslationLookupCreationProcessBatch();
}

public static void main(Args args)
{
    TFMTranslationLookupCreationProcessBatch lookupTranslationLookupProcessBatch = new TFMTranslationLookupCreationProcessBatch();
    lookupTranslationLookupProcessBatch.parmInBatch(true);

    if (lookupTranslationLookupProcessBatch.prompt())
    {
        lookupTranslationLookupProcessBatch.runOperation();
    }
}

/// <summary>
/// Describes whether the class is designed for execution in a new session.
/// </summary>
/// <returns>
/// false.
/// </returns>
protected boolean canRunInNewSession()
{
    return false;
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable() 
{
    return true;
}
